const primMap = { string: 'string', number: 'number', boolean: 'boolean', date: 'Date', uuid: 'string', decimal: 'number' };
function tsTypeFor(a) {
  let base = primMap[a.type];
  if (base === undefined) {
    base = a.aggregation === 'none' ? 'string' : pascalCase(a.type);
  }
  if (a.multiValue) { base += '[]'; }
  return base;
}
const attrs = attributes || [];
attrSpecs = attrs.map(function (a) {
  return {
    camel: camelCase(a.name),
    required: !!a.required,
    tsType: tsTypeFor(a)
  };
});
const prims = ['string','number','boolean','date','uuid','decimal'];
const importTargets = attrs
  .filter(function (a) { return a.aggregation !== 'none'; })
  .map(function (a) { return a.type; })
  .filter(function (t) { return prims.indexOf(t) === -1 && t !== name; });
nonPrimitives = Array.from(new Set(importTargets));

{{#each nonPrimitives}}
import type { {{pascalCase this}} } from './{{pascalCase this}}'
{{/each}}

export type {{pascalCase name}} = {
{{#each attrSpecs}}
  {{camel}}{{#unless required}}?{{/unless}}: {{{tsType}}}
{{/each}}
}
